define('text!templates/playback-controls.html',[],function () { return '<div class="playback-controls-wrapper">\r\n<% if (!dcOnly) { %>\r\n\t<button class="btn btn-normal reset-dynamics-btn" title="Reset Dynamics">Reset Dynamics</button>\r\n<% } %>\r\n\r\n    <div class="playback-center-buttons-wrapper">\r\n        <button class="playback-btn play-btn"   title="Resume"><span class="fa fa-play"></span></button>\r\n        <button class="playback-btn pause-btn"  title="Pause"><span class="fa fa-pause"></span></button>\r\n        <button class="playback-btn step-btn"   title="Step forward"><span class="fa fa-step-forward"></span></button>\r\n    </div>\r\n\r\n    <button class="btn btn-normal reset-btn" title="Reset All">Reset All</button>\r\n</div>';});

define('views/sim',['require','jquery','underscore','common/v3/app/app','common/v3/app/sim','common/v3/tools/stopwatch','models/simulation','views/scene','constants','assets','nouislider','bootstrap','bootstrap-select','less!styles/sim','less!styles/playback-controls','less!common/styles/slider','less!common/styles/radio','less!bootstrap-select-less','text!templates/sim.html','text!templates/playback-controls.html'],function (require) {

    'use strict';

    var $ = require('jquery');
    var _ = require('underscore');

    var AppView       = require('common/v3/app/app');
    var SimView       = require('common/v3/app/sim');
    var StopwatchView = require('common/v3/tools/stopwatch');

    var CCKSimulation = require('models/simulation');
    var CCKSceneView  = require('views/scene');

    var Constants = require('constants');

    var Assets = require('assets');

    require('nouislider');
    require('bootstrap');
    require('bootstrap-select');

    // CSS
    require('less!styles/sim');
    require('less!styles/playback-controls');
    require('less!common/styles/slider');
    require('less!common/styles/radio');
    require('less!bootstrap-select-less');

    // HTML
    var simHtml              = require('text!templates/sim.html');
    var playbackControlsHtml = require('text!templates/playback-controls.html');

    /**
     * 
     */
    var CCKSimView = SimView.extend({

        /**
         * Root element properties
         */
        tagName:   'section',
        className: 'sim-view',

        /**
         * Template for rendering the basic scaffolding
         */
        template:                      _.template(simHtml),
        playbackControlsPanelTemplate: _.template(playbackControlsHtml),

        /**
         * Dom event listeners
         */
        events: {
            'click .play-btn'     : 'play',
            'click .pause-btn'    : 'pause',
            'click .step-btn'     : 'step',
            'click .reset-btn'    : 'reset',

            'click #show-electrons-check'           : 'toggleElectrons',
            'click #show-schematic-check'           : 'toggleSchematic',
            'click #show-values-check'              : 'toggleValues',
            'click #show-voltmeter-check'           : 'toggleVoltmeter',
            'click #show-ammeter-check'             : 'toggleAmmeter',
            'click #show-non-contact-ammeter-check' : 'toggleNonContactAmmeter',
            'click #show-stopwatch-check'           : 'toggleStopwatch',

            'click .zoom-in-btn'  : 'zoomIn',
            'click .zoom-out-btn' : 'zoomOut'
        },

        /**
         * Inits simulation, views, and variables.
         *
         * @params options
         */
        initialize: function(options) {
            options = _.extend({
                title: 'Circuit Construction Kit',
                name: 'cck',
                link: 'circuit-construction-kit-ac',
                dcOnly: false
            }, options);

            this.dcOnly = options.dcOnly;

            SimView.prototype.initialize.apply(this, [options]);

            this.initSceneView();

            this.listenTo(this.simulation, 'change:paused', this.pausedChanged);
            this.pausedChanged(this.simulation, this.simulation.get('paused'));
        },

        /**
         * Initializes the Simulation.
         */
        initSimulation: function() {
            this.simulation = new CCKSimulation();
        },

        /**
         * Initializes the SceneView.
         */
        initSceneView: function() {
            this.sceneView = new CCKSceneView({
                simulation: this.simulation,
                dcOnly: this.dcOnly
            });
        },

        /**
         * Renders everything
         */
        render: function() {
            this.$el.empty();

            this.renderScaffolding();
            this.renderSceneView();
            this.renderPlaybackControls();
            this.renderStopwatchView();

            return this;
        },

        /**
         * Renders page content. Should be overriden by child classes
         */
        renderScaffolding: function() {
            var data = {
                Constants: Constants,
                simulation: this.simulation,
                dcOnly: this.dcOnly
            };
            this.$el.html(this.template(data));
            this.$('select').selectpicker();
        },

        /**
         * Renders the playback controls at the bottom of the screen
         */
        renderPlaybackControls: function() {
            this.$playbackControls = $(this.playbackControlsPanelTemplate({ 
                unique: this.cid,
                dcOnly: this.dcOnly
            }));

            this.$el.append(this.$playbackControls);
        },

        /**
         * Renders the scene view
         */
        renderSceneView: function() {
            this.sceneView.render();
            this.$('.scene-view-placeholder').replaceWith(this.sceneView.el);
            this.$el.append(this.sceneView.$ui);
        },

        /**
         * Renders the stopwatch view
         */
        renderStopwatchView: function() {
            this.stopwatchView = new StopwatchView({
                dragFrame: this.el,
                units : 'sec',
                unitRatio: 1,
                decimals: 4,
                position: {
                    x : AppView.windowIsShort() ? 630 : 622,
                    y : AppView.windowIsShort() ? 326 : 398 
                }
            });

            this.stopwatchView.render();
            this.stopwatchView.hide();

            this.$el.append(this.stopwatchView.el);
        },

        /**
         * Called after every component on the page has rendered to make sure
         *   things like widths and heights and offsets are correct.
         */
        postRender: function() {
            this.sceneView.postRender();
            this.stopwatchView.postRender();
        },

        resetSimulation: function() {
            // Save whether or not it was paused when we reset
            var wasPaused = this.simulation.get('paused');

            // Set pause the updater and reset everything
            this.updater.pause();
            this.updater.reset();
            this.resetComponents();
            this.resetControls();

            // Resume normal function
            this.updater.play();
            this.play();
            this.pausedChanged();
        },

        /**
         * Resets all the components of the view.
         */
        resetComponents: function() {
            SimView.prototype.resetComponents.apply(this);
            
            this.sceneView.reset();
            this.stopwatchView.hide();
        },

        /**
         * Resets all the controls back to their default state.
         */
        resetControls: function() {
            this.$('#show-schematic-check').prop('checked', false);
            this.$('#show-values-check').prop('checked', false);
            this.$('#show-electrons-check').prop('checked', true);

            this.$('#show-voltmeter-check').prop('checked', false);
            this.$('#show-ammeter-check').prop('checked', false);
            this.$('#show-non-contact-ammeter-check').prop('checked', false);
            this.$('#show-stopwatch-check').prop('checked', false);
        },

        /**
         * This is run every tick of the updater.  It updates the wave
         *   simulation and the views.
         */
        update: function(time, deltaTime) {
            // Update the model
            this.simulation.update(time, deltaTime);

            var timeSeconds = time / 1000;
            var dtSeconds   = deltaTime / 1000;

            // Update the scene
            this.sceneView.update(timeSeconds, dtSeconds, this.simulation.get('paused'));
            this.stopwatchView.update(timeSeconds, dtSeconds, this.simulation.get('paused'));
        },

        /**
         * The simulation changed its paused state.
         */
        pausedChanged: function() {
            if (this.simulation.get('paused'))
                this.$el.removeClass('playing');
            else
                this.$el.addClass('playing');
        },

        toggleElectrons: function() {
            if ($(event.target).is(':checked'))
                this.sceneView.showElectrons();
            else
                this.sceneView.hideElectrons();
        },

        toggleSchematic: function() {
            this.simulation.circuit.set('schematic', $(event.target).is(':checked'));
        },

        toggleValues: function() {
            if ($(event.target).is(':checked')) {
                this.simulation.circuit.branches.each(function(branch) {
                    branch.set('showReadout', true);
                });
            }
            else {
                this.simulation.circuit.branches.each(function(branch) {
                    branch.set('showReadout', false);
                });
            }
        },

        toggleVoltmeter: function() {
            if ($(event.target).is(':checked'))
                this.sceneView.showVoltmeter();
            else
                this.sceneView.hideVoltmeter();
        },

        toggleAmmeter: function() {
            if ($(event.target).is(':checked'))
                this.sceneView.showAmmeter();
            else
                this.sceneView.hideAmmeter();
        },

        toggleNonContactAmmeter: function() {
            if ($(event.target).is(':checked'))
                this.sceneView.showNonContactAmmeter();
            else
                this.sceneView.hideNonContactAmmeter();
        },

        toggleStopwatch: function() {
            if ($(event.target).is(':checked'))
                this.stopwatchView.show();
            else
                this.stopwatchView.hide();
        },

        zoomIn: function() {
            this.sceneView.zoomIn();
        },

        zoomOut: function() {
            this.sceneView.zoomOut();
        },

        showHelp: function() {
            this.sceneView.showHelp();
        },

        hideHelp: function() {
            this.sceneView.hideHelp();
        }

    });

    return CCKSimView;
});

define('persistence',['require','jquery','underscore','common/math/vector2','models/circuit','models/junction','models/components/switch','models/components/wire','models/components/resistor','models/components/ac-voltage-source','models/components/battery','models/components/capacitor','models/components/bulb','models/components/series-ammeter','models/components/grab-bag-resistor','models/components/inductor','models/components/circuit-component'],function (require) {

    'use strict';

    var $ = require('jquery');
    var _ = require('underscore');

    var Vector2 = require('common/math/vector2');

    var Circuit          = require('models/circuit');
    var Junction         = require('models/junction');
    var Switch           = require('models/components/switch');
    var Wire             = require('models/components/wire');
    var Resistor         = require('models/components/resistor');
    var ACVoltageSource  = require('models/components/ac-voltage-source');
    var Battery          = require('models/components/battery');
    var Capacitor        = require('models/components/capacitor');
    var Bulb             = require('models/components/bulb');
    var SeriesAmmeter    = require('models/components/series-ammeter');
    var GrabBagResistor  = require('models/components/grab-bag-resistor');
    var Inductor         = require('models/components/inductor');
    var CircuitComponent = require('models/components/circuit-component');

    /**
     * Parses an XML string and creates and returns a circuit object.
     */
    var parseXML = function(xml) {
        var circuit = new Circuit();
        var xmlDoc = $.parseXML(xml);
        var $xml = $(xmlDoc);

        var $circuit = $xml.find('circuit');
        var $junctions = $circuit.find('junction');
        var $branches = $circuit.find('branch');

        $junctions.each(function() {
            var $junction = $(this);
            var x = parseFloat($junction.attr('x'));
            var y = parseFloat($junction.attr('y'));
            var junction = new Junction({
                position: new Vector2(x, y)
            });
            circuit.addJunction(junction);
        });

        $branches.each(function() {
            var $branch = $(this);
            var startIndex = $branch.attr('startJunction') ? parseInt($branch.attr('startJunction')) : -1;
            var endIndex   = $branch.attr('endJunction')   ? parseInt($branch.attr('endJunction'))   : -1;
            if (startIndex >= 0 && endIndex >= 0) {
                var startJunction = circuit.junctions.at(startIndex); // This only works if everything stays in order.
                var endJunction   = circuit.junctions.at(endIndex);
                var branch = toBranch(startJunction, endJunction, $branch);
                circuit.addBranch(branch);
            }
            else
                console.error('Bad File: Branch exists with no junctions!');
        });

        return circuit;
    };

    var toBranch = function(startJunction, endJunction, $xml) {
        var type = trimComponentType($xml.attr('type'));
        
        if (type === 'Wire') {
            return new Wire({
                startJunction: startJunction,
                endJunction: endJunction
            });
        }
        
        var length = parseFloat($xml.attr('length'));
        var height = parseFloat($xml.attr('height'));

        if (type === 'Resistor') {
            return new Resistor({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height,
                resistance: parseFloat($xml.attr('resistance'))
            });
        }
        else if (type === 'ACVoltageSource') {
            return new ACVoltageSource({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height,
                internalResistance: parseFloat($xml.attr('internalResistance')), 
                internalResistanceOn: true,
                amplitude: parseFloat($xml.attr('amplitude')),
                frequency: parseFloat($xml.attr('frequency'))
            });
        }
        else if (type === 'Capacitor') {
            return new Capacitor({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height,
                voltageDrop: parseFloat($xml.attr('voltage')),
                current:     parseFloat($xml.attr('current')),
                capacitance: parseFloat($xml.attr('capacitance'))
            });
        }
        else if (type === 'Battery') {
            return new Battery({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height,
                internalResistance: parseFloat($xml.attr('internalResistance')), 
                internalResistanceOn: true,
                voltageDrop: parseFloat($xml.attr('voltage'))
            });
        }
        else if (type === 'Switch') {
            return new Switch({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height,
                closed: ($xml.attr('closed') && $xml.attr('closed') === 'true')
            });
        }
        else if (type === 'Bulb') {
            return new Bulb({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height,
                width: parseFloat($xml.attr('width')),
                resistance: parseFloat($xml.attr('resistance')),
                connectAtLeft: ($xml.attr('connectAtLeft') && $xml.attr('connectAtLeft') === 'true')
            });
        }
        else if (type === 'SeriesAmmeter') {
            return new SeriesAmmeter({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height
            });
        }
        else if (type === 'GrabBagResistor') {
            return new Resistor({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height,
                resistance: parseFloat($xml.attr('resistance'))
            });
        }
        else if (type === 'Inductor') {
            return new Inductor({
                startJunction: startJunction,
                endJunction: endJunction,
                length: length,
                height: height,
                voltageDrop: parseFloat($xml.attr('voltage')),
                current:     parseFloat($xml.attr('current')),
                inductance:  parseFloat($xml.attr('inductance'))
            });
        }
        
        return null;
    };

    var trimComponentType = function(type) {
        if (type == 'edu.colorado.phet.cck3.circuit.Branch')
            return 'Wire';
        
        return type.substr(type.lastIndexOf('.') + 1);
    };

    /**
     * Converts a circuit object into an XML string and returns it.
     */
    var toXML = function(circuit) {
        var xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
        xml += '<circuit>\n';

        circuit.junctions.each(function(junction, index) {
            var attrs = [];

            attrs.push(['index', index]);
            attrs.push(['x', junction.get('position').x]);
            attrs.push(['y', junction.get('position').y]);

            xml += '    ' + renderElement('junction', attrs) + '\n';
        });

        circuit.branches.each(function(branch, index) {
            var attrs = [];

            var startIndex = circuit.junctions.indexOf(branch.get('startJunction'));
            var endIndex   = circuit.junctions.indexOf(branch.get('endJunction'));

            attrs.push(['index', index]);
            attrs.push(['startJunction', startIndex]);
            attrs.push(['endJunction', endIndex]);

            var length;
            if (branch instanceof CircuitComponent) {
                length = ['length', branch.get('length')];
                attrs.push(length);
                attrs.push(['height', branch.get('height')]);
            }

            var className;
            if (branch instanceof ACVoltageSource) {
                className = 'ACVoltageSource';

                attrs.push(['amplitude', branch.get('amplitude')]);
                attrs.push(['frequency', branch.get('frequency')]);
                attrs.push(['internalResistance', branch.get('internalResistance')]);
            }
            else if (branch instanceof Battery) {
                className = 'Battery';

                attrs.push(['voltage', branch.getVoltageDrop()]);
                attrs.push(['resistance', branch.get('resistance')]);
                attrs.push(['internalResistance', branch.get('internalResistance')]);
            }
            else if (branch instanceof Resistor) {
                className = 'Resistor';

                attrs.push(['resistance', branch.get('resistance')]);
            }
            else if (branch instanceof Bulb) {
                className = 'Bulb';

                attrs.push(['resistance', branch.get('resistance')]);
                attrs.push(['width', branch.get('width')]);
                attrs.push(['schematic', branch.get('isSchematic')]);
                attrs.push(['connectAtLeft', branch.get('connectAtLeft')]);
                length[1] = branch.get('startJunction').getDistance(branch.get('endJunction'));
            }
            else if (branch instanceof Switch) {
                className = 'Switch';

                attrs.push(['closed', branch.get('closed')]);
            }
            else if (branch instanceof Capacitor) {
                className = 'Capacitor';

                attrs.push(['capacitance', branch.get('capacitance')]);
                attrs.push(['voltage', branch.getVoltageDrop()]);
                attrs.push(['current', branch.get('current')]);
            }
            else if (branch instanceof Inductor) {
                className = 'Inductor';

                attrs.push(['inductance', branch.get('inductance')]);
                attrs.push(['voltage', branch.getVoltageDrop()]);
                attrs.push(['current', branch.get('current')]);
            }
            else if (branch instanceof SeriesAmmeter) {
                className = 'SeriesAmmeter';
            }
            else if (branch instanceof Wire) {
                className = 'Wire';
            }
            else if (branch instanceof GrabBagResistor) {
                className = 'GrabBagResistor';
            }

            attrs.push(['type', expandComponentType(className)]);

            xml += '    ' + renderElement('branch', attrs) + '\n';
        });

        xml += '</circuit>';
        return xml;
    };

    var expandComponentType = function(className) {
        var prefix = 'edu.colorado.phet.circuitconstructionkit.model.components.';
        return prefix + className;
    };

    var renderElement = function(name, attrs) {
        var attributesString = _.map(attrs, function(attr) {
            return attr[0] + '="' + attr[1] + '"';
        }).join(' ');

        return '<' + name + ' ' + attributesString + ' />';
    };

    var Persistence = {
        parseXML: parseXML,
        toXML: toXML
    };

    return Persistence;
});


define('less/less!styles/font-awesome',[],function(){});

define('less/less!styles/app',[],function(){});

define('text!templates/app-buttons.html',[],function () { return '<div class="global-buttons-wrapper">\r\n\t<button class="save-btn" title="Save Circuit File"><span class="fa fa-download"></span>&nbsp; Save</button>\r\n    <button class="load-btn" title="Load Circuit File"><span class="fa fa-upload"></span>&nbsp; Load</button>\r\n    <button class="help-btn" title="Toggle Help"><span class="fa fa-question"></span></button>\r\n</div>\r\n\r\n<div class="file-input-wrapper">\r\n\t<input type="file" id="file" name="file" accept=".cck" />\r\n</div>';});

define('views/app',['require','jquery','underscore','file-saver','common/v3/pixi/view/app','views/sim','assets','persistence','less!styles/font-awesome','less!styles/app','text!templates/app-buttons.html'],function(require) {
    
    'use strict';

    var $ = require('jquery');
    var _ = require('underscore');
    require('file-saver');

    var PixiAppView = require('common/v3/pixi/view/app');

    var CCKSimView = require('views/sim');

    var Assets      = require('assets');
    var Persistence = require('persistence');

    require('less!styles/font-awesome');
    require('less!styles/app');

    var settingsDialogHtml = require('text!templates/app-buttons.html');

    var CCKAppView = PixiAppView.extend({

        assets: Assets.getAssetList(),

        simViewConstructors: [
            CCKSimView
        ],

        events: _.extend({}, PixiAppView.prototype.events, {
            'click .help-btn' : 'toggleHelp',
            'click .load-btn' : 'loadBtnClicked',
            'click .save-btn' : 'saveBtnClicked',
            'change #file' : 'fileSelected'
        }),

        render: function() {
            PixiAppView.prototype.render.apply(this);

            this.$el.append(settingsDialogHtml);
        },

        toggleHelp: function() {
            this.$('.help-btn').toggleClass('active');
            
            if (this.$('.help-btn').hasClass('active'))
                this.simViews[0].showHelp();
            else
                this.simViews[0].hideHelp();
        },

        loadBtnClicked: function(event) {
            $('#file').click();
        },

        saveBtnClicked: function(event) {
            this.saveXML();
        },

        fileSelected: function(event) {
            var files = event.target.files;
            var reader = new FileReader();
            if (files.length > 0) {
                var file = files[0];
                var self = this;

                reader.onload = function(event) {
                    self.loadXML(event.target.result);
                };
                reader.readAsText(file);

                $('#file').val('');
            }
        },

        loadXML: function(contents) {
            var circuit = Persistence.parseXML(contents);
            this.simViews[0].simulation.setCircuit(circuit);
        },

        saveXML: function() {
            var xml = Persistence.toXML(this.simViews[0].simulation.circuit);
            var blob = new Blob([xml], {type: 'text/xml;charset=utf-8'});
            window.saveAs(blob, 'circuit.cck');
        }

    });

    return CCKAppView;
});

define('local/views/sim',['require','underscore','views/sim'],function (require) {

    'use strict';

    var _ = require('underscore');

    var CCKSimView = require('views/sim');

    /**
     * "DCOnly" version of the original
     */
    var DCOnlySimView = CCKSimView.extend({

        /**
         * Inits simulation, views, and variables.
         *
         * @params options
         */
        initialize: function(options) {
            options = _.extend({
                link: 'circuit-construction-kit-dc',
                dcOnly: true
            }, options);

            CCKSimView.prototype.initialize.apply(this, [options]);
        }

    });

    return DCOnlySimView;
});

define('local/views/app',['require','views/app','./sim','assets'],function(require) {
    
    'use strict';

    var CCKAppView = require('views/app');
    
    var DCOnlySimView = require('./sim');

    var Assets = require('assets');

    var DCOnlyAppView = CCKAppView.extend({

        assets: Assets.getAssetList(),

        simViewConstructors: [
            DCOnlySimView
        ]

    });

    return DCOnlyAppView;
});

(function () {
    'use strict';

    // Load the config
    require(['config'], function () {
        require(['jquery', 'local/views/app'], function($, DCOnlyAppView) {

            $(function(){
                var appView = new DCOnlyAppView();

                // Append to body
                $('body').append(appView.el);

                // Render main app view
                appView.load();
            });
    
        });
    });

})();

